stack = []
for match in tag_pattern.finditer(content):
    is_closing = match.group(1) == '/'
    tag_name = match.group(2)
    
    # Check if this tag is self-closing by looking for '/>' after it
    # or if it's a known void/icon
    is_self = tag_name in void_elements or tag_name in icons
    
    # Check for actual /> in the string
    tag_end_pos = content.find('>', match.end())
    if tag_end_pos != -1:
        if content[tag_end_pos-1] == '/':
            is_self = True
            
    if not is_self:
        if is_closing:
            if stack and stack[-1] == tag_name:
                stack.pop()
        else:
            stack.append(tag_name)

print(f"Required closing tags: {stack}")
